import { ERRORS, OPTIONS, validate } from '../';

describe('validate', () => {
  it('should run nothing', () => {
    expect(validate([], 'test')).toEqual([]);
  });

  it('should run func', () => {
    const fake = jest.fn();
    validate([fake], '25.6');
    expect(fake.mock.calls).toHaveLength(1);
  });

  it('should run integer', () => {
    expect(validate(['fakeValidator', OPTIONS.integer], '25.6')).toEqual([
      ERRORS.invalidInteger,
    ]);
  });

  it('should run number', () => {
    expect(validate(['fakeValidator', OPTIONS.number], '25.6h')).toEqual([
      ERRORS.invalidNumber,
    ]);
  });

  it('should run required', () => {
    expect(validate(['fakeValidator', OPTIONS.required], 'test')).toEqual([]);
  });
});
